function card(p,i=0){return `<article class="product-card reveal" style="--enter:${i%2===0?'75px':'-75px'};--delay:${(i%4)*75}ms" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(nameOf(p))}"><div class="product-image"><img loading="lazy" decoding="async" src="${esc(imageUrl(p.image))}" alt="${esc(nameOf(p))}">${p.featured?`<span class="tag">${t('featured')}</span>`:''}</div><div class="product-body"><h3>${esc(nameOf(p))}</h3><p>${esc(p[getLang()==='ar'?'descriptionAr':'descriptionEn']||categoryName(p.category))}</p><div class="product-bottom"><span class="price">${Number(p.price).toLocaleString(getLang()==='ar'?'ar-SA':'en-US')} ${t('sar')}</span><span class="cal">${p.cal?esc(p.cal)+' '+t('kcal'):''}</span></div></div></article>`}
function observe(){const items=document.querySelectorAll('.reveal:not(.visible)');if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(e=>e.classList.add('visible'));return}const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.07});items.forEach(e=>io.observe(e))}
function renderCatalog(){const visible=products.filter(p=>p.visible!==false);$('categoryBar').innerHTML=[{key:'all',ar:t('all'),en:t('all')},...CATEGORIES].map(c=>`<button class="category-pill ${activeCategory===c.key?'active':''}" data-category="${c.key}">${esc((CATEGORY_EXTRA[getLang()]||{})[c.key]||c[getLang()]||c.en)}</button>`).join('');let list=visible.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&Number(p.price)<=maxPrice&&(!lowCal||(Number(p.cal)>0&&Number(p.cal)<250))&&[p.ar,p.en,p.descriptionAr,p.descriptionEn,categoryName(p.category)].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>nameOf(a).localeCompare(nameOf(b),getLang()));$('catalogGrid').innerHTML=list.length?list.map(card).join(''):`<p class="empty">${t('noProducts')}</p>`;observe()}
function renderCollections(){const visible=products.filter(p=>p.visible!==false);$('collectionRails').innerHTML=CATEGORIES.map(c=>{const list=visible.filter(p=>p.category===c.key);if(!list.length)return '';return `<div class="collection" id="section-${c.key}"><div class="section-banner"><div><h2>${esc((CATEGORY_EXTRA[getLang()]||{})[c.key]||c[getLang()]||c.en)}</h2><p>${list.length} ${t('catalog')}</p></div><div class="slider-controls"><button data-scroll="${c.key}" data-dir="-1" aria-label="Previous">‹</button><button data-scroll="${c.key}" data-dir="1" aria-label="Next">›</button></div></div><div class="rail" id="rail-${c.key}">${list.map(card).join('')}</div></div>`}).join('');observe()}
function renderSort(){const old=$('sort').value||sort;$('sort').innerHTML=[['default','sortDefault'],['low','sortLow'],['high','sortHigh'],['name','sortName']].map(([v,k])=>`<option value="${v}">${t(k)}</option>`).join('');$('sort').value=old}
function translate(){const lang=getLang();document.documentElement.dir=['ar','ku'].includes(lang)?'rtl':'ltr';document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$('langBtn').textContent=lang.toUpperCase();$('languagePicker').value=lang;renderSort();renderCatalog();renderCollections();renderAdminList();if(activeDetail)openDetail(activeDetail)}
function showOverlay(id){$(id).classList.add('open');document.body.style.overflow='hidden'}function closeOverlay(id){$(id).classList.remove('open');if(!document.querySelector('.overlay.open'))document.body.style.overflow='';if(id==='detailOverlay')activeDetail=null}
function openDetail(id){const p=products.find(x=>x.id===id);if(!p)return;activeDetail=id;const gallery=[p.image,...(Array.isArray(p.gallery)?p.gallery:[])].filter(Boolean);const desc=p[getLang()==='ar'?'descriptionAr':'descriptionEn'];const allerg=p[getLang()==='ar'?'allergensAr':'allergensEn'];const sizes=Array.isArray(p.sizes)?p.sizes:[];const similar=products.filter(x=>x.visible!==false&&x.category===p.category&&x.id!==p.id).slice(0,3);$('detailContent').innerHTML=`<div class="detail-grid"><div><img class="detail-image" id="detailMainImage" src="${esc(imageUrl(gallery[0]))}" alt="${esc(nameOf(p))}"><div class="thumbs">${gallery.map((g,i)=>`<img data-thumb="${i}" src="${esc(imageUrl(g))}" alt="${esc(nameOf(p))} ${i+1}">`).join('')}</div></div><div class="detail-copy"><div class="kicker">${esc(categoryName(p.category))}</div><h2>${esc(nameOf(p))}</h2><div class="price">${esc(p.price)} ${t('sar')}</div><p>${esc(desc||'')}</p>${p.cal?`<p>♨ ${esc(p.cal)} ${t('kcal')}</p>`:''}<h3>${t('sizes')}</h3><p>${sizes.map(s=>`${esc(s[getLang()]||s.ar||'')} ${Number(s.price)===Number(p.price)?'':`— ${esc(s.price)} ${t('sar')}`}`).join(' · ')||'—'}</p><h3>${t('ingredients')}</h3><p>${esc(allerg||t('allergyNotice'))}</p><p class="notice">${t('allergyNotice')}</p></div></div>${similar.length?`<h3>${t('related')}</h3><div class="product-grid">${similar.map(card).join('')}</div>`:''}`;showOverlay('detailOverlay');observe()}
function renderAdminList(){$('adminCount').textContent=products.length+' '+t('catalog');$('adminList').innerHTML=products.map(p=>`<div class="admin-item"><img src="${esc(imageUrl(p.image))}" alt=""><div class="name"><strong>${esc(nameOf(p))}</strong><div class="cal">${esc(categoryName(p.category))} · ${esc(p.price)} ${t('sar')}</div></div><button class="btn" data-edit="${esc(p.id)}">${t('edit')}</button><button class="btn" data-toggle="${esc(p.id)}">${p.visible!==false?t('hide'):t('show')}</button><button class="btn" data-delete="${esc(p.id)}">${t('delete')}</button></div>`).join('');$('formCategory').innerHTML=CATEGORIES.map(c=>`<option value="${c.key}">${esc((CATEGORY_EXTRA[getLang()]||{})[c.key]||c[getLang()]||c.en)}</option>`).join('')}
function editProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('productId').value=p.id;$('nameAr').value=p.ar||'';$('nameEn').value=p.en||'';$('formCategory').value=p.category;$('formPrice').value=p.price;$('formCal').value=p.cal||0;$('formImage').value=/^https:\/\//.test(p.image)?p.image:'';$('formGallery').value=(p.gallery||[]).join('\n');$('formDescAr').value=p.descriptionAr||'';$('formDescEn').value=p.descriptionEn||'';$('formSizesAr').value=(p.sizes||[]).map(s=>s.ar).join(', ');$('formSizesEn').value=(p.sizes||[]).map(s=>s.en).join(', ');$('formAllergensAr').value=p.allergensAr||'';$('formAllergensEn').value=p.allergensEn||'';$('formVisible').checked=p.visible!==false;$('formFeatured').checked=!!p.featured;$('productForm').scrollIntoView({behavior:'smooth',block:'nearest'})}
function newProduct(){$('productForm').reset();$('productId').value='';$('formVisible').checked=true;$('formCategory').value=CATEGORIES[0].key}
function refresh(){renderCatalog();renderCollections();renderAdminList()}
function initHero(){const slides=$('heroSlides');slides.innerHTML=HERO_IMAGES.map((u,i)=>`<div class="hero-slide ${i===0?'active':''}"><img src="${esc(u)}" alt="Patisserie scene ${i+1}" ${i?'loading="lazy"':''}></div>`).join('');$('heroDots').innerHTML=HERO_IMAGES.map((_,i)=>`<button class="dot ${i===0?'active':''}" data-hero="${i}" aria-label="Slide ${i+1}"></button>`).join('');function go(i){heroIndex=(i+HERO_IMAGES.length)%HERO_IMAGES.length;document.querySelectorAll('.hero-slide').forEach((e,n)=>e.classList.toggle('active',n===heroIndex));document.querySelectorAll('.dot').forEach((e,n)=>e.classList.toggle('active',n===heroIndex))}function start(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;heroTimer=setInterval(()=>go(heroIndex+1),5500)}function stop(){clearInterval(heroTimer)}$('heroPrev').onclick=()=>go(heroIndex-1);$('heroNext').onclick=()=>go(heroIndex+1);$('heroDots').onclick=e=>{const d=e.target.closest('[data-hero]');if(d)go(Number(d.dataset.hero))};$('home').addEventListener('mouseenter',stop);$('home').addEventListener('mouseleave',start);document.addEventListener('visibilitychange',()=>{stop();if(!document.hidden)start()});start()}
function exportData(){const blob=new Blob([JSON.stringify({version:5,products},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='maison-sucre-v5-products.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function validProduct(p){return p&&typeof p==='object'&&typeof p.id==='string'&&typeof p.ar==='string'&&typeof p.en==='string'&&CATEGORIES.some(c=>c.key===p.category)&&Number.isFinite(Number(p.price))&&Number(p.price)>=0&&Number(p.price)<=100000&&(!p.image||/^https:\/\//.test(p.image))}
function share(){const u=location.href;if(navigator.share&&location.protocol!=='file:'){navigator.share({title:document.title,url:u}).catch(()=>{})}else if(navigator.clipboard&&location.protocol!=='file:'){navigator.clipboard.writeText(u).then(()=>alert(t('shareCopied'))).catch(()=>prompt('Copy URL',u))}else prompt('Copy URL',u)}
function showQr(){const c=$('qrContent');if(!/^https?:$/.test(location.protocol)||location.hostname==='localhost'){c.textContent=t('qrLocal')}else{const url='https://api.qrserver.com/v1/create-qr-code/?size=240x240&data='+encodeURIComponent(location.href);c.innerHTML=`<img style="max-width:240px;margin:0 auto" src="${esc(url)}" alt="QR code">`}showOverlay('qrOverlay')}
$('languagePicker').onchange=e=>{document.documentElement.lang=e.target.value;try{localStorage.setItem('maison-v5-lang',e.target.value)}catch{}translate()};$('langBtn').onclick=()=>{const languages=['ar','en','ku','fr','de'];const lang=languages[(languages.indexOf(getLang())+1)%languages.length];document.documentElement.lang=lang;try{localStorage.setItem('maison-v5-lang',lang)}catch{}translate()};$('themeBtn').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('maison-v5-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};$('search').oninput=e=>{query=e.target.value.trim();renderCatalog()};$('sort').onchange=e=>{sort=e.target.value;renderCatalog()};$('priceRange').oninput=e=>{maxPrice=Number(e.target.value);$('priceValue').textContent=maxPrice;renderCatalog()};$('lowCal').onchange=e=>{lowCal=e.target.checked;renderCatalog()};$('categoryBar').onclick=e=>{const b=e.target.closest('[data-category]');if(b){activeCategory=b.dataset.category;renderCatalog()}};document.addEventListener('click',e=>{const product=e.target.closest('.product-card');if(product){openDetail(product.dataset.id);return}const scroll=e.target.closest('[data-scroll]');if(scroll){const rail=$('rail-'+scroll.dataset.scroll);if(rail)rail.scrollBy({left:Number(scroll.dataset.dir)*290,behavior:'smooth'});return}const close=e.target.closest('[data-close]');if(close)closeOverlay(close.dataset.close);const thumb=e.target.closest('[data-thumb]');if(thumb){const p=products.find(x=>x.id===activeDetail);const g=[p.image,...(p.gallery||[])];$('detailMainImage').src=imageUrl(g[Number(thumb.dataset.thumb)])}});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay.open').forEach(x=>closeOverlay(x.id));if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('product-card')){e.preventDefault();openDetail(e.target.dataset.id)}});document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)closeOverlay(el.id)}));$('adminBtn').onclick=()=>{renderAdminList();showOverlay('adminOverlay')};$('newProduct').onclick=newProduct;$('adminList').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit){editProduct(b.dataset.edit)}else if(b.dataset.toggle){const p=products.find(x=>x.id===b.dataset.toggle);p.visible=p.visible===false;save();refresh()}else if(b.dataset.delete){if(confirm(t('confirmDelete'))){products=products.filter(x=>x.id!==b.dataset.delete);save();refresh()}}};$('productForm').onsubmit=e=>{e.preventDefault();const id=$('productId').value||('custom-'+Date.now());const existing=products.find(x=>x.id===id);const arSizes=$('formSizesAr').value.split(',').map(s=>s.trim()).filter(Boolean),enSizes=$('formSizesEn').value.split(',').map(s=>s.trim()).filter(Boolean);const price=Number($('formPrice').value);const item={id,ar:$('nameAr').value.trim(),en:$('nameEn').value.trim(),category:$('formCategory').value,price,cal:Number($('formCal').value)||0,image:$('formImage').value.trim()||existing?.image||'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=700&q=80',gallery:$('formGallery').value.split(/\n/).map(s=>s.trim()).filter(s=>/^https:\/\//.test(s)),descriptionAr:$('formDescAr').value.trim(),descriptionEn:$('formDescEn').value.trim(),allergensAr:$('formAllergensAr').value.trim(),allergensEn:$('formAllergensEn').value.trim(),sizes:arSizes.map((s,i)=>({ar:s,en:enSizes[i]||s,price})),visible:$('formVisible').checked,featured:$('formFeatured').checked};if(!validProduct(item))return alert(t('importError'));if(existing)products[products.indexOf(existing)]=item;else products.unshift(item);save();refresh();newProduct();alert(t('saved'))};$('exportBtn').onclick=exportData;$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.products)||data.products.length>3000||!data.products.every(validProduct)||new Set(data.products.map(x=>x.id)).size!==data.products.length)throw Error('invalid');products=data.products;save();refresh();newProduct()}catch{alert(t('importError'))}e.target.value=''};$('resetBtn').onclick=()=>{if(confirm(t('confirmReset'))){products=structuredClone(DEFAULT_PRODUCTS);save();refresh();newProduct()}};$('shareBtn').onclick=share;$('qrBtn').onclick=showQr;
try{const l=localStorage.getItem('maison-v5-lang');if(['ar','en','ku','fr','de'].includes(l))document.documentElement.lang=l;if(localStorage.getItem('maison-v5-theme')==='dark')document.body.classList.add('dark')}catch{}$('priceValue').textContent=maxPrice;initHero();translate();newProduct();


/* V6 add-ons: all storage is browser-local; no fake cloud sync */
const V6_TEXT={ar:{menu:'عرض المنيو',popular:'الأكثر مشاهدة هنا',share:'مشاركة الكتالوج',cakeTitle:'فن الكيك الفاخر',cakeText:'طبقات من المذاق والتفاصيل، مصممة لتجعل كل مناسبة أجمل.',coffeeTitle:'قهوة تستحق اللحظة',coffeeText:'من الإسبريسو إلى المشروبات الباردة، اكتشف نكهاتنا المميزة.',discover:'استكشف المنتجات',print:'طباعة / PDF',close:'إغلاق',campaignAdmin:'إدارة شريط الموسم (على هذا المتصفح فقط)',campaignAr:'عنوان الموسم بالعربية',campaignEn:'عنوان الموسم بالإنجليزية',start:'تاريخ البداية',end:'تاريخ النهاية',saveCampaign:'حفظ شريط الموسم',localNote:'هذه الإعدادات محلية ولن تظهر للزوار على أجهزة أخرى قبل ربط قاعدة بيانات.',photos:'اضغط على الصورة لفتح معرض الصور',popularLabel:'الأكثر مشاهدة على هذا الجهاز'},en:{menu:'Digital Menu',popular:'Popular on this device',share:'Share Catalog',cakeTitle:'The Art of Signature Cakes',cakeText:'Layers of flavor and detail, crafted for unforgettable occasions.',coffeeTitle:'Coffee Worth Savoring',coffeeText:'From espresso to iced favorites, explore our curated coffee selection.',discover:'Explore Products',print:'Print / PDF',close:'Close',campaignAdmin:'Seasonal Banner (this browser only)',campaignAr:'Arabic seasonal headline',campaignEn:'English seasonal headline',start:'Start date',end:'End date',saveCampaign:'Save Seasonal Banner',localNote:'Settings are local to this browser and will not sync to visitors without a database.',photos:'Tap the image for a full-screen gallery',popularLabel:'Most viewed on this device'}};
function v6Lang(){return ['ar','ku'].includes(document.documentElement.lang)?'ar':'en'}
function v6T(key){return V6_TEXT[v6Lang()][key]||key}
function v6Translate(){document.querySelectorAll('[data-v6]').forEach(e=>e.textContent=v6T(e.dataset.v6));v6CampaignRender();if(document.getElementById('v6Menu').classList.contains('open'))v6RenderMenu()}
function v6Get(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function v6Set(key,val){try{localStorage.setItem(key,JSON.stringify(val))}catch{}}
function v6CampaignRender(){const c=v6Get('maison-v6-campaign',{}),el=document.getElementById('v6Season');const today=new Date().toLocaleDateString('en-CA');const valid=(!c.start||today>=c.start)&&(!c.end||today<=c.end);el.textContent=c[v6Lang()]||'';el.hidden=!(valid&&el.textContent)}
function v6RenderMenu(){const visible=products.filter(p=>p.visible!==false);document.getElementById('v6MenuContent').innerHTML=CATEGORIES.map(c=>{const list=visible.filter(p=>p.category===c.key);if(!list.length)return '';return `<section class="v6-menu-section"><h2>${esc(c[v6Lang()])}</h2><div class="v6-menu-grid">${list.map(p=>`<div class="v6-menu-item"><img src="${esc(imageUrl(p.image))}" alt=""><div><strong>${esc(nameOf(p))}</strong><div>${Number(p.price).toLocaleString(v6Lang()==='ar'?'ar-SA':'en-US')} ${t('sar')}</div>${p.cal?`<small>${esc(p.cal)} ${t('kcal')}</small>`:''}</div></div>`).join('')}</div></section>`}).join('')}
function v6OpenMenu(){v6RenderMenu();document.getElementById('v6Menu').classList.add('open');document.body.style.overflow='hidden'}
function v6CloseMenu(){document.getElementById('v6Menu').classList.remove('open');document.body.style.overflow=''}
let v6Gallery=[],v6GalleryIndex=0;
function v6ShowPhoto(index){if(!v6Gallery.length)return;v6GalleryIndex=(index+v6Gallery.length)%v6Gallery.length;document.getElementById('v6LightImage').src=imageUrl(v6Gallery[v6GalleryIndex]);document.getElementById('v6LightCount').textContent=`${v6GalleryIndex+1} / ${v6Gallery.length}`;document.getElementById('v6Lightbox').classList.add('open')}
function v6ClosePhoto(){document.getElementById('v6Lightbox').classList.remove('open')}
function v6Init(){
 const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('v6-in');obs.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.v6-reveal').forEach(e=>obs.observe(e));if(matchMedia('(prefers-reduced-motion:reduce)').matches)document.querySelectorAll('.v6-reveal').forEach(e=>e.classList.add('v6-in'));
 document.getElementById('v6MenuButton').onclick=v6OpenMenu;document.getElementById('v6CloseMenu').onclick=v6CloseMenu;document.getElementById('v6PrintMenu').onclick=()=>window.print();document.getElementById('v6ShareButton').onclick=()=>{if(typeof share==='function')share();else navigator.clipboard?.writeText(location.href)};
 document.getElementById('v6PopularButton').onclick=()=>{const counts=v6Get('maison-v6-views',{});const ids=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8).map(x=>x[0]);const list=ids.map(id=>products.find(p=>p.id===id&&p.visible!==false)).filter(Boolean);const grid=document.getElementById('catalogGrid');if(list.length){grid.innerHTML=`<h3 style="grid-column:1/-1">${v6T('popularLabel')}</h3>`+list.map(card).join('');observe();grid.scrollIntoView({behavior:'smooth'})}else{alert(v6Lang()==='ar'?'لا توجد مشاهدات مسجلة على هذا الجهاز بعد.':'No product views recorded on this device yet.')}};
 document.addEventListener('click',e=>{if(e.target.id==='detailMainImage'){const p=products.find(x=>x.id===activeDetail);if(!p)return;v6Gallery=[p.image,...(p.gallery||[])].filter(Boolean);const img=document.getElementById('detailMainImage');let ix=v6Gallery.findIndex(u=>imageUrl(u)===img.src);v6ShowPhoto(ix<0?0:ix)}});
 document.getElementById('v6LightClose').onclick=v6ClosePhoto;document.getElementById('v6LightPrev').onclick=()=>v6ShowPhoto(v6GalleryIndex-1);document.getElementById('v6LightNext').onclick=()=>v6ShowPhoto(v6GalleryIndex+1);
 document.addEventListener('keydown',e=>{if(!document.getElementById('v6Lightbox').classList.contains('open')){if(e.key==='Escape')v6CloseMenu();return}if(e.key==='Escape')v6ClosePhoto();if(e.key==='ArrowLeft')v6ShowPhoto(v6GalleryIndex-1);if(e.key==='ArrowRight')v6ShowPhoto(v6GalleryIndex+1)});
 let x0=null;document.getElementById('v6Lightbox').addEventListener('touchstart',e=>{x0=e.touches[0].clientX},{passive:true});document.getElementById('v6Lightbox').addEventListener('touchend',e=>{if(x0!==null&&Math.abs(e.changedTouches[0].clientX-x0)>50)v6ShowPhoto(v6GalleryIndex+(e.changedTouches[0].clientX<x0?1:-1));x0=null},{passive:true});
 const oldDetail=openDetail;openDetail=function(id){const counts=v6Get('maison-v6-views',{});counts[id]=(counts[id]||0)+1;v6Set('maison-v6-views',counts);oldDetail(id);const img=document.getElementById('detailMainImage');if(img){img.classList.add('v6-photo-button');img.title=v6T('photos')}};
 const oldTranslate=translate;translate=function(){oldTranslate();v6Translate()};
 const c=v6Get('maison-v6-campaign',{});for(const [id,key] of [['v6CampaignAr','ar'],['v6CampaignEn','en'],['v6Start','start'],['v6End','end']])document.getElementById(id).value=c[key]||'';
 document.getElementById('v6SaveCampaign').onclick=()=>{const c={ar:document.getElementById('v6CampaignAr').value.trim(),en:document.getElementById('v6CampaignEn').value.trim(),start:document.getElementById('v6Start').value,end:document.getElementById('v6End').value};if(c.start&&c.end&&c.start>c.end){alert(v6Lang()==='ar'?'تاريخ النهاية قبل البداية':'End date precedes start date');return}v6Set('maison-v6-campaign',c);v6CampaignRender();alert(t('saved'))};
 v6Translate();
}
v6Init();
